  const PANEL_POS_KEY = "codex_wechat_mp_exporter_panel_pos_v1";
  const PANEL_COLLAPSED_KEY = "codex_wechat_mp_exporter_collapsed_v1";

  const PAGE_SIZE = 10;
  const API_DELAY_RANGE_MS = [5000, 12000];
  const CONTENT_DELAY_RANGE_MS = [9000, 22000];
  const PAGE_CLICK_DELAY_RANGE_MS = [4000, 9000];
  const SCROLL_DELAY_RANGE_MS = [2500, 6500];
  const ERROR_BACKOFF_RANGE_MS = [45000, 90000];
  const MAX_RETRIES = 2;

  const METRIC_COLUMNS = [
    "read_num",
    "like_num",
    "share_num",
    "favorite_or_collect_num",
    "comment_num",
    "metric_6",
    "metric_7",
    "metric_8",
    "api_moment_like_num",
  ];

  const EXPORT_COLUMNS = [
    "appmsg_id",
    "publish_time",
    "title",
    "status",
    ...METRIC_COLUMNS,
    "is_deleted",
    "source",
    "content_url",
    "cover_url",
    "article_title",
    "article_author",
    "article_publish_time",
    "article_text_len",
    "article_fetch_status",
    "article_fetch_error",
    "article_text",
    "collected_at",
  ];

  const STATE = {
    running: false,
    rows: loadRows(),
    totalCount: 0,
    collapsed: localStorage.getItem(PANEL_COLLAPSED_KEY) === "1",
    toastTimer: null,
    lastDownload: null,
    stopRequested: false,
    activeController: null,
    currentTask: "Idle",
  };

  installNetworkHooks();
  onReady(() => {
    installPanel();
    setTimeout(scanVisible, 1400);
  });

  function onReady(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  function setCurrentTask(task) {
    STATE.currentTask = task || "Idle";
    updateTaskLine();
  }

  function finishCurrentTask() {
    setCurrentTask(STATE.stopRequested ? "Paused" : "Idle");
  }

  async function interruptibleSleep(ms) {
    const end = Date.now() + ms;
    while (Date.now() < end) {
      if (STATE.stopRequested || !STATE.running) return false;
      await sleep(Math.min(500, end - Date.now()));
    }
    return true;
  }

  function randomDelay(range) {
    const [min, max] = range;
    return Math.floor(min + Math.random() * Math.max(0, max - min));
  }

  async function politeDelay(label, range) {
    const ms = randomDelay(range);
    updatePanel(`${label}: waiting ${Math.ceil(ms / 1000)}s...`);
    return interruptibleSleep(ms);
  }

  async function withRetries(label, task) {
    let lastError = null;
    for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
      if (STATE.stopRequested || !STATE.running) throw new Error("Task paused");
      try {
        return await task();
      } catch (error) {
        if (STATE.stopRequested || error?.name === "AbortError") throw new Error("Task paused");
        lastError = error;
        if (attempt >= MAX_RETRIES) break;
        const shouldContinue = await politeDelay(`${label} failed, retry ${attempt + 1}/${MAX_RETRIES}`, ERROR_BACKOFF_RANGE_MS);
        if (!shouldContinue) throw new Error("Task paused");
      }
    }
    throw lastError;
  }

  function safeInt(value, fallback = "") {
    if (value === undefined || value === null || value === "") return fallback;
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function firstNonEmpty(...values) {
    for (const value of values) {
      if (value !== undefined && value !== null && value !== "") return value;
    }
    return "";
  }

